import math
from typing import List


def first_n_primes(n: int) -> List[int]:
    primes: List[int] = []
    c = 2
    while len(primes) < n:
        if all(c % p for p in primes if p * p <= c):
            primes.append(c)
        c += 1
    return primes


def total_persistence(primes: List[int]) -> int:
    return sum(primes[i + 1] - primes[i] for i in range(len(primes) - 1))


if __name__ == '__main__':
    print(f"{'n':>6}{'TP(n)':>10}{'p_n-2':>10}{'match':>7}{'TP/(nlogn)':>12}")
    for n in [10, 100, 1000, 5000]:
        primes = first_n_primes(n)
        tp = total_persistence(primes)
        pred = primes[-1] - 2
        ratio = tp / (n * math.log(n))
        print(f'{n:>6}{tp:>10}{pred:>10}{str(tp == pred):>7}{ratio:>12.4f}')

from typing import List, Tuple


def first_n_primes(n: int) -> List[int]:
    primes: List[int] = []
    c = 2
    while len(primes) < n:
        if all(c % p for p in primes if p * p <= c):
            primes.append(c)
        c += 1
    return primes


def prime_gaps(primes: List[int]) -> List[int]:
    return [primes[i + 1] - primes[i] for i in range(len(primes) - 1)]


def betti0(eps: float, primes: List[int]) -> int:
    return 1 + sum(1 for g in prime_gaps(primes) if g > eps)


def betti_curve(primes: List[int]) -> List[Tuple[float, int]]:
    gaps = sorted(set(prime_gaps(primes)))
    return [(0.0, len(primes))] + [(float(g), betti0(float(g), primes)) for g in gaps]


if __name__ == '__main__':
    primes = first_n_primes(30)
    print('Betti curve (eps, b0):')
    for eps, b in betti_curve(primes):
        print(f'  eps={eps:>5}  b0={b}')
    print('global merge scale =', max(prime_gaps(primes)))
